import { UserRepository } from '../repositories/user-repository.js';

const users = new UserRepository();

export function listActiveUsers() {
  return users.findActive();
}

export function findUser(id) {
  return users.findById(id);
}

export function softDeleteUser(id, when) {
  return users.softDelete(id, when);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { listActiveUsers, findUser } from '../src/services/user-service.js';

test('listActiveUsers excludes soft-deleted users', async () => {
  const users = await listActiveUsers();
  assert.equal(users.length, 2);
  assert.ok(users.every((u) => u.deleted_at === null));
});

test('findUser returns null for an unknown id', async () => {
  const user = await findUser(999);
  assert.equal(user, null);
});
